import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.DMvgf4hZ.js";const g=JSON.parse('{"title":"视频合成","description":"","frontmatter":{},"headers":[],"relativePath":"guide/video.md","filePath":"guide/video.md","lastUpdated":1794745517000}'),i={name:"guide/video.md"};function s(n,t,l,d,c,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="视频合成" tabindex="-1">视频合成 <a class="header-anchor" href="#视频合成" aria-label="Permalink to &quot;视频合成&quot;">​</a></h1><p>把分镜图变成可用的镜头，再按顺序整理成一支短片。整条链路都在画布上完成：图片节点提供画面，视频生成节点产出镜头，素材库负责归档。</p><h2 id="一条可复现的合成路径" tabindex="-1">一条可复现的合成路径 <a class="header-anchor" href="#一条可复现的合成路径" aria-label="Permalink to &quot;一条可复现的合成路径&quot;">​</a></h2><ol><li><strong>备好分镜</strong>：先用文本节点写清镜头描述，用图片生成节点产出每个镜头的画面，或用 3D 导演台导出构图参考图。</li><li><strong>逐镜头生成视频</strong>：把画面连到“视频生成”节点，选择支持图片参考的视频模型，按镜头写运镜与动作描述，逐个生成。</li><li><strong>检查运动</strong>：在节点中播放，逐条确认镜头运动是否自然；不理想就改提示词重生成，或用“创建副本”保留旧结果对比。</li><li><strong>归档与导出</strong>：满意的镜头“保存到素材库”，再在节点上点击下载图标导出成片素材。</li></ol><div class="tip custom-block"><p class="custom-block-title">生成设置怎么选</p><p>打开视频生成节点下方的生成设置，按模型支持的能力选择图片参考模式、时长、分辨率与比例。参考素材、时长、分辨率和音频能力都取决于所选模型与供应商。</p></div><h2 id="对话也可以是-agent" tabindex="-1">对话也可以是 Agent <a class="header-anchor" href="#对话也可以是-agent" aria-label="Permalink to &quot;对话也可以是 Agent&quot;">​</a></h2><p>右侧对话框可以直接驱动合成流程：描述你要的成片，Agent 会拆解分镜、准备素材、串联节点，再按你的确认推进。适合一次说清整支短片的需求，细节再逐个镜头微调。具体用法见 <a href="./agent.html">Agent 助手</a>。</p><div class="info custom-block"><p class="custom-block-title">关于本页演示视频</p><p>原教程本节的演示视频体积超过 140 MB，未包含在文档站内。按上面四步即可复现同样的流程。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>生成的视频没有声音？</strong></p><p>音频能力由所选模型与供应商决定，生成设置中允许开启音频时才可能带声音。也可以单独生成音频节点，在后续剪辑中合成。</p><p><strong>镜头之间风格不统一？</strong></p><p>固定同一套参考图与文本描述，只改变运镜与动作部分；换模型或换提示词风格会让前后镜头差异变大。</p>',13)])])}const _=a(i,[["render",s]]);export{g as __pageData,_ as default};
